  'board_risk.obl_dora_incident': { et: 'Intsidentidest teavitamine 4h jooksul', en: 'Incident reporting within 4 hours' },
  'board_risk.obl_none': { et: 'See ettevõte ei kuulu NIS2/DORA regulatsiooni alla', en: 'This company is not subject to NIS2/DORA regulations' },

  // Board Risk - Accordion
  'board_risk.acc1_title': { et: 'NIS2 Art. 20 — Juhtimisorganite vastutus', en: 'NIS2 Art. 20 — Management Body Liability' },
  'board_risk.acc1_content': { et: 'Juhtorganid peavad kiitma heaks küberturbe riskijuhtimise meetmed ja vastutavad isiklikult nende rakendamise eest. Juhtorganite liikmed peavad läbima küberturbe koolituse.', en: 'Management bodies must approve cybersecurity risk management measures and are personally liable for their implementation. Management body members must undergo cybersecurity training.' },
  'board_risk.acc2_title': { et: 'Trahvid ja sanktsioonid', en: 'Fines and Sanctions' },
  'board_risk.acc2_content': { et: 'Elutähtis üksus: kuni €10M või 2% käibest. Oluline üksus: kuni €7M või 1,4% käibest. Juhatuse liikme isiklik trahv kuni €500K. DORA: kuni €5M või 2% käibest.', en: 'Essential entity: up to €10M or 2% of turnover. Important entity: up to €7M or 1.4% of turnover. Board member personal fine up to €500K. DORA: up to €5M or 2% of turnover.' },
  'board_risk.acc3_title': { et: 'Millal vastutus rakendub?', en: 'When Does Liability Apply?' },
  'board_risk.acc3_content': { et: 'Kui rikkumine on tuvastatud ja juhatuse liige ei suuda tõestada mõistlike meetmete rakendamist. Vastutus võib tekkida ka hooletuse korral, kui juhatus ei ole küberturbe riske piisavalt adresseerinud.', en: 'When a violation is detected and the board member cannot prove implementation of reasonable measures. Liability may also arise from negligence if the board has not adequately addressed cybersecurity risks.' },
  'board_risk.acc4_title': { et: 'Kuidas ennast kaitsta?', en: 'How to Protect Yourself?' },
  'board_risk.acc4_content': { et: '1. Dokumenteeri kõik küberturbe otsused juhatuse protokollis. 2. Läbi küberturbe koolitus ja säilita tunnistus. 3. Kinnita riskihindamise tulemused formaalselt. 4. Taga intsidentide teavitamise protsess. 5. Kontrolli IKT-pakkujate vastavust regulaarselt.', en: '1. Document all cybersecurity decisions in board minutes. 2. Complete cybersecurity training and retain certificate. 3. Formally approve risk assessment results. 4. Ensure incident reporting process is in place. 5. Regularly verify ICT provider compliance.' },

