  'board_risk.cta1_desc': { et: 'Kompaktne PDF sinu isiklike kohustuste ja riskidega.', en: 'Compact PDF with your personal obligations and risks.' },
  'board_risk.cta1_btn': { et: 'Telli raport', en: 'Order report' },
