  // About page
  'nav.about': { et: 'Meist', en: 'About' },
  'about.title': { et: 'DORA Art. 30 meeskond', en: 'DORA Art. 30 Team' },
  'about.subtitle': { et: 'Ehitame Eesti finantssektorile automatiseeritud vastavuskontrolli', en: 'Building automated compliance checking for the Estonian financial sector' },
  'about.mission_title': { et: 'Meie missioon', en: 'Our mission' },
  'about.mission_desc': { et: 'DORA regulatsioon nõuab kõigilt finantssektori ettevõtetelt, et nende IKT-lepingud vastaksid rangetele nõuetele. Me automatiseerime selle kontrolli, säästes teile aega ja raha.', en: 'DORA regulation requires all financial sector companies to have ICT contracts that meet strict requirements. We automate this check, saving you time and money.' },
  'about.why_title': { et: 'Miks me seda teeme', en: 'Why we do this' },
  'about.why_1': { et: 'DORA kohaldub alates 2025. aastast kõigile EL finantssektori ettevõtetele', en: 'DORA applies from 2025 to all EU financial sector companies' },
  'about.why_2': { et: 'Manuaalne lepingute kontroll on aeglane ja kallis (juristide tunnihind 200-400 EUR)', en: 'Manual contract review is slow and expensive (lawyer hourly rate 200-400 EUR)' },
  'about.why_3': { et: 'Trahvid mittevastavuse eest võivad ulatuda kuni 2% aastasest käibest', en: 'Fines for non-compliance can reach up to 2% of annual turnover' },
  'about.why_4': { et: 'Eestis puudus seni eestikeelne automatiseeritud lahendus', en: 'Estonia lacked an Estonian-language automated solution until now' },
  'about.founder_title': { et: 'Asutaja', en: 'Founder' },
  'about.founder_bio': { et: 'Tarkvaraarendaja ja regulatiivse tehnoloogia spetsialist 10+ aasta kogemusega. Erikompetents finantssektori compliance automatiseerimises, DORA ja NIS2 regulatsioonide rakendamises.', en: 'Software engineer and regulatory technology specialist with 10+ years of experience. Specializing in financial sector compliance automation, DORA and NIS2 regulation implementation.' },
  'about.stats_title': { et: 'Numbrid', en: 'By the numbers' },
  'about.stat_requirements': { et: 'DORA Art. 30 nõuet', en: 'DORA Art. 30 requirements' },
  'about.stat_analysis': { et: 'lepingu analüüs', en: 'contract analysis' },
  'about.stat_penalty': { et: 'maksimaalne trahv käibest', en: 'max penalty of revenue' },
  'about.stat_regulations': { et: 'regulatsiooni kaetud', en: 'regulations covered' },
  'about.tech_title': { et: 'Tehnoloogia', en: 'Technology' },
  'about.tech_desc': { et: 'Meie platvorm on ehitatud kaasaegsete tehnoloogiatega ja turvaliselt.', en: 'Our platform is built with modern technologies and securely.' },
  'about.tech_1': { et: 'Andmed ainult EL serverites', en: 'Data only on EU servers' },
  'about.tech_2': { et: 'AES-256 krüpteerimine', en: 'AES-256 encryption' },
  'about.tech_3': { et: 'GDPR-konformne', en: 'GDPR compliant' },
  'about.tech_4': { et: 'Automaatne skaleerumine', en: 'Auto-scaling infrastructure' },
  'about.methodology_title': { et: 'Metoodika', en: 'Methodology' },
  'about.methodology_desc': { et: 'DoraAudit metoodika põhineb DORA (EU) 2022/2554 ametlikul tekstil, Euroopa Pangandusjärelevalve (EBA) ja ESMA tehnilisel standarditel, Eesti Finantsinspektsiooni juhistel ning E-ITS raamistikul. Analüüsimudelid on välja töötatud koostöös finantssektori compliance spetsialistidega.', en: 'DoraAudit methodology is based on the official text of DORA (EU) 2022/2554, EBA and ESMA technical standards, Estonian Financial Supervision Authority guidelines, and the E-ITS framework. Analysis models have been developed in collaboration with financial sector compliance specialists.' },
  'about.contact_title': { et: 'Võta ühendust', en: 'Get in touch' },
  'about.contact_desc': { et: 'Küsimused, demo soov või enterprise pakkumine', en: 'Questions, demo request, or enterprise offer' },
  'about.contact_email': { et: 'info@doraaudit.eu', en: 'info@doraaudit.eu' },

