  'fine.gap_q1': { et: 'Puuduv ICT riskijuhtimise raamistik suurendab trahviriski oluliselt. DORA Art. 6-16 nõuab kõigilt finantsasutustelt ICT riskide tuvastamist, hindamist ja maandamist.', en: 'Missing ICT risk management framework significantly increases fine risk. DORA Art. 6-16 requires all financial entities to identify, assess and mitigate ICT risks.' },
  'fine.gap_q2': { et: 'Puuduv intsidentide raporteerimise protsess on tõsine rikkumine. DORA Art. 17-23 nõuab kõigi oluliste ICT intsidentide raporteerimist järelevalveasutusele.', en: 'Missing incident reporting process is a serious violation. DORA Art. 17-23 requires reporting of all major ICT incidents to supervisory authorities.' },
  'fine.gap_q3': { et: 'DORA Art. 30 nõuetele mittevastavad ICT lepingud on üks sagedasemaid rikkumisi. Lepingud peavad sisaldama konkreetseid teenustaseme kokkuleppeid ja auditeerimisõigusi.', en: 'ICT contracts not complying with DORA Art. 30 is one of the most common violations. Contracts must include specific SLAs and audit rights.' },
  'fine.gap_q4': { et: 'Testimisprogrammi puudumine tähendab, et te ei suuda tõestada oma digitaalset vastupidavust. DORA Art. 24-27 nõuab regulaarset testimist.', en: 'Missing testing program means you cannot demonstrate digital resilience. DORA Art. 24-27 requires regular testing.' },
